INSERT INTO items (item_type_id, content, answer_set, word_count, difficulty, cefr_level, status, pool, topic, exam_part_id, exam_order) VALUES
('passage_reconstruction', '{"passage": "Maria arrived at the office early to prepare for the client presentation. When she opened her laptop, she realized the file was missing from her drive. She quickly called her colleague, who emailed her a backup copy. By the time the client arrived, Maria was fully ready and the meeting went smoothly."}'::jsonb, '{"key_points": ["Maria arrived early to prepare", "the file was missing", "a colleague emailed a backup copy", "the meeting went smoothly"]}'::jsonb, 55, 0.55, 'B2', 'approved', 'exam', 'work', 'a1000000-0000-4000-8000-000000000016', 1),
('passage_reconstruction', '{"passage": "David had been saving money for a new bicycle for several months. Last weekend, he finally visited the shop downtown and found the exact model he wanted. The salesperson offered him a small discount because it was the last one in stock. David happily paid and rode it home that same afternoon."}'::jsonb, '{"key_points": ["David had been saving for a bicycle", "he found the model he wanted", "he got a discount since it was the last one", "he rode it home that afternoon"]}'::jsonb, 56, 0.60, 'B2', 'approved', 'exam', 'daily-life', 'a1000000-0000-4000-8000-000000000016', 2);
